def _recommendation_template_entry(
    *,
    season_nm: str,
    rcmd_type: str = "all_weather",
    limit: int | None = None,
    requested_limit: int | None = None,
    effective_limit: int | None = None,
    item_count: int = 1,
) -> dict:
    args = {
        "rcmd_type": rcmd_type,
        "season_nm": season_nm,
        "tire_size": "235/55R19",
    }
    if limit is not None:
        args["limit"] = limit
    data = {
        "items": [
            {
                "goods_no": f"G{i}",
                "goods_nm": f"벤투스 에어S {i}",
                "tire_size_1": "235/55R19",
                "season_nm": season_nm,
            }
            for i in range(1, item_count + 1)
        ]
    }
    if requested_limit is not None:
        data["requested_limit"] = requested_limit
    if effective_limit is not None:
        data["effective_limit"] = effective_limit
    return {
        "tool": "get_products_recommendations_tool",
        "args": args,
        "data": {
            "status": "success",
            "http_status": 200,
            "data": data,
        },
    }


