def test_support_faq_policy_event_for_assurance_service_does_not_append_long_source_summary() -> None:
    event = _build_support_faq_policy_event(
        "assurance_service_policy",
        "안심서비스랑 안심플러스 보상 조건이 정확히 어떻게 돼?",
        tool_result={
            "status": "success",
            "data": {
                "items": [
                    {
                        "answer": (
                            "안심서비스와 안심플러스는 전국 티스테이션 매장, 더타이어샵 매장, 티스테이션닷컴 공식 홈페이지, "
                            "네이버 스마트스토어에서 타이어 구매 시 가입 또는 적용이 가능합니다. "
                            "안심서비스는 타이어 2개 이상 구매 시 고객 과실로 파손되더라도 새 타이어 1개를 보상받을 수 있습니다."
                        )
                    }
                ]
            },
        },
    )

    assert event is not None
    response = str(event["data"]["assistantResponse"])
    lines = [line for line in response.splitlines() if line.strip()]
    assert "장착 후 1년 이내" in lines[0]
    assert "16,000km 이내" in lines[0]
    assert len(response) < 260
    assert "안심서비스는 타이어 2개 이상 구매 시 고객 과실로 파손되더라도 새 타이어 1개를 보상받을 수 있습니다." not in response
    assert "안심서비스는 2개 이상, 안심플러스는 4개 구매 기준" in response
    assert event["data"]["metadata"]["faqSourceSummaryUsed"] is True
    assert event["data"]["metadata"]["faqSourceSummaryAppended"] is False
    assert not response.endswith("...")


def test_direct_faq_policy_tool_payload_builds_transaction_policy_event() -> None:
    contract = build_turn_contract(
        user_text="예약 취소하면 비용 발생해?",
        intent_frame=IntentFrame(domain=PolicyDomain.TRANSACTION, intent="general_cancel_fee_policy"),
        tool_plan=ToolPlan(
            allowed_tools=("search_faq_hybrid_tool",),
            preferred_tool="search_faq_hybrid_tool",
            forbidden_tools=("get_orders_of_user_tool",),
            metadata={"response_intent": "general_cancel_fee_policy"},
        ),
        response_decision=ResponseDecision(
            response_shape=ResponseShape.SUMMARY,
            template=TemplateName.QUICK_REPLY,
            metadata={"response_shape_key": "general_cancel_fee_policy_summary"},
        ),
        routing_result=_routing_result(
            domains=[MultiAgentDomain.Domain.TRANSACTION],
            execution_plan=["transaction:general_cancel_fee_policy"],
        ),
    )
    payload = _build_direct_faq_policy_tool_payload(
        turn_contract=contract,
        user_query="예약 취소하면 비용 발생해?",
        raw_tool_result={
            "status": "success",
            "data": {"items": [{"answer": "장착 예약만 취소하는 경우 별도의 취소 수수료는 없습니다."}]},
        },
    )

    assert payload is not None
    tool_input, tool_result, event = payload
    assert tool_input == {"query": "예약 취소하면 비용 발생해?", "top_k": 8}
    assert tool_result["status"] == "success"
    assert event["source_domain"] in {"transaction", "support"}
    assert event["data"]["metadata"]["responseShapeKey"] == "general_cancel_fee_policy_summary"


